import Foundation
import SourceryRuntime
import SwiftSyntax

extension GenericType {
    convenience init(name: String, node: GenericArgumentClauseSyntax) {
        #if compiler(>=6.2)
        // TODO: ExprSyntax may need to be handled
        let parameters = node.arguments.map { argument -> GenericTypeParameter? in
            switch argument.argument {
            case .type(let type):
                return GenericTypeParameter(typeName: TypeName(type))
            default: // case .expr
                return nil
            }
        }.compactMap({ $0 })
        #else
        let parameters = node.arguments.map { argument in
            GenericTypeParameter(typeName: TypeName(argument.argument))
        }
        #endif

        self.init(name: name, typeParameters: parameters)
    }
}

import Foundation
import SourceryRuntime
import SwiftSyntax

extension SyntaxProtocol {
    @inlinable
    var sourcerySafeTypeIdentifier: String {
        let content = description
        return String(content[content.utf8.index(content.startIndex, offsetBy: leadingTriviaLength.utf8Length)..<content.utf8.index(content.endIndex, offsetBy: -trailingTriviaLength.utf8Length)])

        // TBR: we only need this because we are trying to fit into old AST naming
        // TODO: there is a bug in syntax that sometimes crashes with unexpected nil when removing trivia

